"""Verified Gmsh-cell mapping and conservative sampled-volume RF heating transfer."""
import hashlib
import json
from pathlib import Path
import numpy as np
from ..records import digest,read_json,write_json
from .spatial_maps import bin_indices
from .mesh import CELL


def read_tetrahedra(path):
    """Read the linear ASCII Gmsh 4.1 meshes generated by helicon.rf.mesh."""
    text=Path(path).read_text()
    def section(name):
        try:return text.split('$'+name+'\n',1)[1].split('$End'+name,1)[0].strip().splitlines()
        except IndexError:raise ValueError('Missing Gmsh section '+name) from None
    if section('MeshFormat')[0].split()[:2]!=['4.1','0']:
        raise ValueError('Require an ASCII Gmsh 4.1 mesh; binary/higher-order conversion is not implicit')
    lines=section('Entities');counts=list(map(int,lines[0].split()));pos=1;regions={}
    for dim,count in enumerate(counts):
        for line in lines[pos:pos+count]:
            fields=line.split();offset=4 if dim==0 else 7;n=int(fields[offset])
            if dim==3:
                if n!=1:raise ValueError('Require exactly one physical region per volume entity')
                regions[int(fields[0])]=int(fields[offset+1])
        pos+=count
    tokens=iter(' '.join(section('Nodes')).split())
    blocks,total,_,_=[int(next(tokens)) for _ in range(4)]
    tags=[];points=[]
    for _ in range(blocks):
        dim,entity,parametric,n=[int(next(tokens)) for _ in range(4)]
        if parametric:raise ValueError('Parametric Gmsh nodes are unsupported')
        tags.extend(int(next(tokens)) for _ in range(n))
        points.extend([float(next(tokens)) for _ in range(3)] for _ in range(n))
    if len(tags)!=total or len(set(tags))!=total:raise ValueError('Invalid Gmsh node count/tags')
    order=np.argsort(tags);tags=np.asarray(tags,dtype=np.int64)[order];points=np.asarray(points)[order]
    lines=section('Elements');blocks,total,_,_=map(int,lines[0].split());pos=1;ids=[];vertices=[];material=[]
    for _ in range(blocks):
        dim,entity,kind,n=map(int,lines[pos].split());pos+=1
        block=lines[pos:pos+n];pos+=n
        if dim!=3:continue
        if kind!=4:raise ValueError('Only linear tetrahedra are supported')
        for line in block:
            values=list(map(int,line.split()))
            if len(values)!=5:raise ValueError('Invalid tetrahedron connectivity')
            nodes=np.asarray(values[1:],dtype=np.int64);indices=np.searchsorted(tags,nodes)
            if np.any(indices>=len(tags)) or not np.array_equal(tags[indices],nodes):
                raise ValueError('Tetrahedron references missing nodes')
            ids.append(values[0]);vertices.append(points[indices]);material.append(regions[entity])
    vertices=np.asarray(vertices);ids=np.asarray(ids,dtype=np.int64);material=np.asarray(material)
    if not len(ids) or len(np.unique(ids))!=len(ids) or not np.isfinite(vertices).all():
        raise ValueError('Invalid Gmsh tetrahedra')
    volume=np.abs(np.linalg.det(vertices[:,1:]-vertices[:,:1]))/6
    if np.any(volume<=0):raise ValueError('Degenerate mesh tetrahedra')
    return ids,vertices,material,volume


def exports(directory):
    paths=sorted(Path(directory).glob('cells_rank*.npz'))
    summary=read_json(Path(directory)/'rf_summary.json')
    ranks=summary['mpi_ranks']
    if paths!=[Path(directory)/f'cells_rank{i:04d}.npz' for i in range(ranks)]:
        raise ValueError('Missing or extra MPI cell-export shards')
    arrays={key:[] for key in ('xyz_m','region','cell_volume_m3','cell_absorbed_power_W')}
    for path in paths:
        with np.load(path,allow_pickle=False) as data:
            n=len(data['region'])
            for key in arrays:
                a=data[key]
                expected=(n,3) if key=='xyz_m' else (n,)
                if a.shape!=expected or not np.isfinite(a).all():raise ValueError('Invalid RF export '+key)
                arrays[key].append(a.copy())
    arrays={k:np.concatenate(v) for k,v in arrays.items()}
    if np.any(arrays['cell_volume_m3']<=0):raise ValueError('Nonpositive exported cell volume')
    identity={p.name:digest(p) for p in [Path(directory)/'rf.msh',*paths]}
    return arrays,identity


def payload_hash(ids,vertices):
    h=hashlib.sha256();h.update(ids.tobytes());h.update(vertices.tobytes());return h.hexdigest()


def map_cells(directory,out,cache=None):
    """Match ALL owned exports, requiring a bijection within region/centroid/volume tolerances."""
    from scipy.spatial import cKDTree
    if Path(out).exists(): raise FileExistsError(out)
    arrays,identity=exports(directory)
    if cache is not None:
        with np.load(cache,allow_pickle=False) as data:
            info=json.loads(str(data['metadata'].item()))
            ids=data['gmsh_element_ids'].copy();vertices=data['vertices_m'].copy()
        if (info.get('version')!=1 or info['input_sha256']!=identity or
                info['payload_sha256']!=payload_hash(ids,vertices) or
                vertices.shape!=(len(arrays['region']),4,3) or len(ids)!=len(vertices) or
                len(np.unique(ids))!=len(ids)):
            raise ValueError('Mapping cache identity/content mismatch')
        if not np.allclose(vertices.mean(axis=1),arrays['xyz_m'],rtol=0,atol=info['centroid_tolerance_m']):
            raise ValueError('Mapping cache centroid mismatch')
        volumes=np.abs(np.linalg.det(vertices[:,1:]-vertices[:,:1]))/6
        if not np.allclose(volumes,arrays['cell_volume_m3'],rtol=1e-8,atol=1e-24):
            raise ValueError('Mapping cache volume mismatch')
        info['loaded_from_cache']=True
    else:
        mesh_ids,mesh_vertices,regions,volumes=read_tetrahedra(Path(directory)/'rf.msh')
        if len(mesh_ids)!=len(arrays['region']):raise ValueError('Mesh/export cell count differs')
        centers=mesh_vertices.mean(axis=1)
        tolerance=max(1e-12,1e-10*float(np.ptp(mesh_vertices,axis=(0,1)).max()))
        mapping=np.full(len(mesh_ids),-1,dtype=np.int64)
        for region in np.unique(regions):
            source=np.flatnonzero(regions==region);target=np.flatnonzero(arrays['region']==region)
            if len(source)!=len(target):raise ValueError('Mesh/export region cell count differs')
            candidates=cKDTree(centers[source]).query_ball_point(arrays['xyz_m'][target],tolerance)
            for index,near in zip(target,candidates):
                near=source[np.asarray(near,dtype=int)]
                matches=near[np.isclose(volumes[near],arrays['cell_volume_m3'][index],rtol=1e-8,atol=1e-24)]
                if len(matches)!=1:raise ValueError(f'Exported cell {index}: ambiguous or missing mesh match ({len(matches)})')
                mapping[index]=matches[0]
        if np.any(mapping<0) or len(np.unique(mapping))!=len(mapping):
            raise ValueError('Mesh/export mapping is not a bijection')
        ids=mesh_ids[mapping];vertices=mesh_vertices[mapping]
        info={'version':1,'input_sha256':identity,'centroid_tolerance_m':tolerance,
              'volume_relative_tolerance':1e-8,'matched_cells':len(mapping),
              'payload_sha256':payload_hash(ids,vertices),'loaded_from_cache':False,
              'max_centroid_error_m':float(np.linalg.norm(vertices.mean(axis=1)-arrays['xyz_m'],axis=1).max()),
              'max_volume_relative_error':float(np.max(abs(volumes[mapping]/arrays['cell_volume_m3']-1)))}
    np.savez_compressed(out,gmsh_element_ids=ids,vertices_m=vertices,metadata=np.array(json.dumps(info)))
    return arrays,vertices,info


def deposit(vertices,power,volumes,grid,barycentric):
    """Every uniform-volume sample carries 1/N of its tetrahedron's power and volume."""
    n=len(barycentric);p=np.zeros(grid.size);v=np.zeros(grid.size)
    batch=max(1,min(128,131072//n))
    for start in range(0,len(vertices),batch):
        stop=min(start+batch,len(vertices))
        xyz=np.einsum('sk,bkj->bsj',barycentric,vertices[start:stop]).reshape(-1,3)
        ir,iz=bin_indices(xyz,grid.rf,grid.zf);bins=iz*grid.shape[1]+ir
        p+=np.bincount(bins,weights=np.repeat(power[start:stop]/n,n),minlength=grid.size)
        v+=np.bincount(bins,weights=np.repeat(volumes[start:stop]/n,n),minlength=grid.size)
    return p.reshape(grid.shape),v.reshape(grid.shape)


def heating(directory,grid,expected_power_W,out,samples=512,rtol=.005,cache=None):
    """Two nested deterministic Sobol sample levels; fail if coverage/stability gates fail."""
    from scipy.stats import qmc
    out=Path(out);out.mkdir(parents=True,exist_ok=False)
    if isinstance(samples,bool) or not isinstance(samples,int) or samples<16 or samples>65536 or samples&(samples-1):
        raise ValueError('Transfer samples must be a power of two in [16, 65536]')
    if not np.isfinite(rtol) or not 0<rtol<.1:raise ValueError('Transfer rtol must be in (0, 0.1)')
    arrays,vertices,mapping=map_cells(directory,out/'mesh_mapping.npz',cache)
    mask=arrays['region']==CELL['PLASMA'];power=arrays['cell_absorbed_power_W'][mask];volumes=arrays['cell_volume_m3'][mask]
    if not len(power) or np.any(power<0) or not np.isfinite(expected_power_W) or expected_power_W<=0:
        raise ValueError('Require positive integrated passive plasma power')
    error=abs(power.sum()-expected_power_W)/expected_power_W
    if error>1e-6:raise ValueError('RF-to-plasma transfer does not conserve original power')
    points=qmc.Sobol(d=4,scramble=True,seed=20261105).random_base2(int(np.log2(samples))+1)
    exponential=-np.log(np.clip(points,np.finfo(float).tiny,1.))
    barycentric=exponential/exponential.sum(axis=1,keepdims=True)
    coarse,cv=deposit(vertices[mask],power,volumes,grid,barycentric[:samples])
    fine,fv=deposit(vertices[mask],power,volumes,grid,barycentric)
    change=float(np.sum(abs(fine-coarse))/power.sum())
    volume_change=float(np.sum(abs(fv-cv))/volumes.sum())
    covered=bool(np.all(fv>0) and np.all(cv>0))
    conservation=float(abs(fine.sum()-expected_power_W)/expected_power_W)
    passed=bool(covered and change<=rtol and volume_change<=rtol and conservation<1e-6)
    info={'method':'uniform tetrahedron-volume Sobol sampling; azimuthally summed',
        'assumption':'Uniform absorption density within each RF tetrahedron. Sampling does not restore unresolved RF fields.',
        'coverage_definition':'Sampled geometric volume, independent of deposited power; not exact overlap certification.',
        'mapping':mapping,'integrated_power_W':float(fine.sum()),'relative_power_error':conservation,
        'occupied_bin_fraction':float(np.mean(fv>0)),'coarse_occupied_bin_fraction':float(np.mean(cv>0)),
        'empty_bins_iz_ir':np.argwhere(fv<=0).tolist(),
        'rf_plasma_volume_m3':float(volumes.sum()),'fv_plasma_volume_m3':float(grid.volumes.sum()),
        'coarse_samples_per_tetrahedron':samples,'samples_per_tetrahedron':2*samples,
        'power_distribution_L1_relative_change':change,'volume_distribution_L1_relative_change':volume_change,
        'sampling_relative_tolerance':rtol,'sampling_checks_passed':passed,
        'note':'Two-level sampling stability is not a rigorous integration error bound or mesh convergence.'}
    np.savez_compressed(out/'transfer_samples.npz',power_coarse_W=coarse,power_fine_W=fine,
        volume_coarse_m3=cv,volume_fine_m3=fv,r_faces_m=grid.rf,z_faces_m=grid.zf)
    write_json(out/'transfer_diagnostics.json',info)
    if not passed:raise ValueError(f'Sampled transfer checks failed: coverage={info["occupied_bin_fraction"]:g}, '
        f'power change={change:g}, volume change={volume_change:g}; inspect {out}/transfer_diagnostics.json')
    return fine/grid.volumes,info


def main():
    import argparse
    import sys
    from .. import spatial
    from ..config import load as load_geometry
    from .prescribed import inspect_rf
    from .run import snapshot
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--rf-solution',required=True)
    parser.add_argument('--plasma-config',required=True)
    parser.add_argument('--geometry')
    parser.add_argument('--out',required=True)
    parser.add_argument('--samples',type=int,default=512)
    parser.add_argument('--rtol',type=float,default=.005)
    parser.add_argument('--mapping',help='Previously verified mesh_mapping.npz')
    parser.add_argument('--allow-exploratory-interface',action='store_true')
    args=parser.parse_args()
    existed=Path(args.out).exists()
    try:
        c=spatial.load(args.plasma_config);geometry=load_geometry(args.geometry)
        rf,wave,hashes,acceptance=inspect_rf(args.rf_solution,geometry,args.allow_exploratory_interface)
        grid=spatial.Grid(geometry,c['nr'],c['nz'])
        q,info=heating(args.rf_solution,grid,wave['material_absorption_W']['PLASMA'],
                       args.out,args.samples,args.rtol,args.mapping)
        out=Path(args.out)
        if any(digest(Path(args.rf_solution)/name)!=sha for name,sha in hashes.items()):
            raise ValueError('RF inputs changed during transfer')
        np.savez_compressed(out/'heating.npz',q_abs_W_m3=q,r_faces_m=grid.rf,z_faces_m=grid.zf)
        write_json(out/'run.json',{'status':'completed','input_sha256':hashes,
            'rf_configuration':rf,'plasma_config':c,'geometry':geometry,
            'interface_acceptance':acceptance,'source':snapshot(out),'transfer':info})
        print(f"Mapped {info['mapping']['matched_cells']} cells; "
              f"covered bins={info['occupied_bin_fraction']:.6g}; "
              f"power error={info['relative_power_error']:.3g}; "
              f"sampling power/volume changes={info['power_distribution_L1_relative_change']:.3g}/"
              f"{info['volume_distribution_L1_relative_change']:.3g}")
        print(f'Transfer check completed: {args.out}/transfer_diagnostics.json')
        return 0
    except Exception as exc:
        if not existed and Path(args.out).is_dir() and not isinstance(exc,FileExistsError):
            write_json(Path(args.out)/'run.json',{'status':'failed','error':str(exc)})
        print(f'Transfer check stopped: {exc}',file=sys.stderr)
        return 2


if __name__=='__main__':
    raise SystemExit(main())
